"""Auto-generated TouchDesigner Network Builder: Course 04: MediaPipe / Depth Body Tracking + Hysteresis Smoothing & OSC Out

Captures webcam/depth tracking, applies Lag/Filter CHOP hysteresis smoothing, and broadcasts /sensor/skeleton OSC to UE 5.8 & vvvv.
Generated by Mo360 Antigravity <-> TouchDesigner Bridge (Mode B).
Run inside TouchDesigner Textport or pass via startup script.
"""

import json

PROJECT_NAME = 'course04_interactive_sensors_pervasive'
PARENT_PATH = '/project1'
TARGET_FPS = 60


def _resolve_op(op_type_name):
    import td
    if hasattr(td, op_type_name):
        return getattr(td, op_type_name)
    low = op_type_name.lower()
    for attr in dir(td):
        if attr.lower() == low:
            return getattr(td, attr)
    raise ValueError(f"Unknown TouchDesigner operator type: {op_type_name}")


def _set_params(node, params):
    for key, val in params.items():
        if hasattr(node.par, key):
            setattr(node.par, key, val)


def build_network(parent_path=PARENT_PATH):
    import td
    td.project.cookRate = TARGET_FPS
    root = op(parent_path)
    if root is None:
        root = op('/').create(td.baseCOMP, parent_path.strip('/'))

    comp = root.op('course04_interactive_sensors_pervasive')
    if comp is not None:
        comp.destroy()
    comp = root.create(td.baseCOMP, 'course04_interactive_sensors_pervasive')
    comp.nodeX = 0
    comp.nodeY = 0

    created = {}
    # Webcam / Depth Sensor Input
    _node = comp.create(_resolve_op('videodeviceinTOP'), 'cam_depth_in')
    _node.nodeX = 0
    _node.nodeY = 220
    _set_params(_node, {'resolutionw': 1280, 'resolutionh': 720})
    created['cam_depth_in'] = _node
    # Visitor Silhouette & Centroid Tracker
    _node = comp.create(_resolve_op('blobtrackTOP'), 'blob_track')
    _node.nodeX = 240
    _node.nodeY = 220
    _set_params(_node, {'threshold': 0.42})
    created['blob_track'] = _node
    # External MediaPipe / LiDAR OSC
    _node = comp.create(_resolve_op('oscinCHOP'), 'osc_sensor_in')
    _node.nodeX = 0
    _node.nodeY = 40
    _set_params(_node, {'port': 9002})
    created['osc_sensor_in'] = _node
    # Jitter Removal Filter CHOP
    _node = comp.create(_resolve_op('filterCHOP'), 'filter_smooth')
    _node.nodeX = 260
    _node.nodeY = 40
    _set_params(_node, {'filterwidth': 0.25})
    created['filter_smooth'] = _node
    # Asymmetric Rise/Fall Hysteresis
    _node = comp.create(_resolve_op('lagCHOP'), 'lag_hysteresis')
    _node.nodeX = 480
    _node.nodeY = 40
    _set_params(_node, {'lag1': 0.18, 'lag2': 0.45})
    created['lag_hysteresis'] = _node
    # Presence Trigger Gate
    _node = comp.create(_resolve_op('logicCHOP'), 'logic_presence')
    _node.nodeX = 700
    _node.nodeY = 40
    _set_params(_node, {'preop': 'off', 'bound': True})
    created['logic_presence'] = _node
    # Send /sensor/skeleton to UE 5.8
    _node = comp.create(_resolve_op('oscoutCHOP'), 'osc_out_ue')
    _node.nodeX = 930
    _node.nodeY = 120
    _set_params(_node, {'address': '127.0.0.1', 'port': 7000})
    created['osc_out_ue'] = _node
    # Send /sensor/skeleton to vvvv 4V
    _node = comp.create(_resolve_op('oscoutCHOP'), 'osc_out_vvvv')
    _node.nodeX = 930
    _node.nodeY = -40
    _set_params(_node, {'address': '127.0.0.1', 'port': 8000})
    created['osc_out_vvvv'] = _node

    # Wire signal flow
    created['blob_track'].inputConnectors[0].connect(created['cam_depth_in'].outputConnectors[0])
    created['filter_smooth'].inputConnectors[0].connect(created['osc_sensor_in'].outputConnectors[0])
    created['lag_hysteresis'].inputConnectors[0].connect(created['filter_smooth'].outputConnectors[0])
    created['logic_presence'].inputConnectors[0].connect(created['lag_hysteresis'].outputConnectors[0])
    created['osc_out_ue'].inputConnectors[0].connect(created['logic_presence'].outputConnectors[0])
    created['osc_out_vvvv'].inputConnectors[0].connect(created['logic_presence'].outputConnectors[0])

    print(f"[Mo360-TD] Built {len(created)} operators inside {comp.path}")
    return comp


if __name__ == "__main__":
    build_network()
